 static int focusedPanel;
 static void RestoreFocusedPanel(){ExtraPanel p;if(focusedPanel!=0&&extraPanels.TryGetValue(focusedPanel,out p)&&!fixture)Place(p.handle,p.placement,false);focusedPanel=0;}
 static object FocusPanelCommand(Dictionary<string,object> c){int id=(int)Number(c,"panelId",0);if(id<0||id>4||id!=0&&!extraPanels.ContainsKey(id))throw new Exception("Choose an open capture panel.");RestoreFocusedPanel();if(id==0)return new{panelId=0};if(!watchEnabled||watchStyle!="toolbar")throw new Exception("Choose Toolbar wrist style first.");if(!fixture){uint device=system.GetTrackedDeviceIndexForControllerRole(watchAnchor=="wrist-left"?ETrackedControllerRole.LeftHand:ETrackedControllerRole.RightHand);if(device==OpenVR.k_unTrackedDeviceIndexInvalid)throw new Exception("The watch controller is unavailable.");var wrist=WatchTransform(watchAnchor);var above=Rotation(0,25);above.m7=.24f;above.m11=-.08f;var transform=Multiply(wrist,above);Check(OpenVR.Overlay.SetOverlayTransformTrackedDeviceRelative(ExtraHandle(id),device,ref transform));Check(OpenVR.Overlay.SetOverlayWidthInMeters(ExtraHandle(id),.60f));Check(OpenVR.Overlay.ShowOverlay(ExtraHandle(id)));}focusedPanel=id;return new{panelId=id};}
 const int WatchWidth=1024,WatchHeight=512;
 static bool fixtureWatchLooking=true;
 static ulong watchHandle;static bool watchEnabled,watchVisible,watchArmed;static string watchAnchor="wrist-left",watchStyle="toolbar";static double watchWidth=.14,lastWatchCheck;
