 // Dorsal mount: outward X is the back-of-hand side of a controller grip.
 // Keep the face beside the grip; its normal points inward toward the wearer.
 static HmdMatrix34_t WatchTransform(string anchor){bool left=anchor=="wrist-left";var m=Rotation(left?90:-90,0);m.m3=left?-.065f:.065f;m.m7=.015f;m.m11=.035f;return m;}
 // Head-forward gaze and the watch's front normal must both agree. No pointing-to-arm step.
 static bool WatchInView(HmdMatrix34_t head,HmdMatrix34_t face,bool showing){double x=face.m3-head.m3,y=face.m7-head.m7,z=face.m11-head.m11,d=Math.Sqrt(x*x+y*y+z*z);if(d<.12||d>1.2)return false;double gaze=(-head.m2*x-head.m6*y-head.m10*z)/d,facing=(-face.m2*x-face.m6*y-face.m10*z)/d;return gaze>(showing?.80:.88)&&facing>.25;}
 static void WatchVisibility(){if(fixture)SetWatchVisible(watchEnabled&&fixtureVisible&&fixtureWatchLooking);}
 static void SetWatchVisible(bool next){if(next==watchVisible)return;watchVisible=next;watchArmed=next;if(!fixture&&watchHandle!=0){Check(OpenVR.Overlay.SetOverlayFlag(watchHandle,VROverlayFlags.MakeOverlaysInteractiveIfVisible,next));if(next&&surfaces.ContainsKey(watchHandle))Check(OpenVR.Overlay.ShowOverlay(watchHandle));else Check(OpenVR.Overlay.HideOverlay(watchHandle));if(focusedPanel!=0&&ExtraHandle(focusedPanel)!=0){if(next&&capturesVisible&&!extraPanels[focusedPanel].hidden)Check(OpenVR.Overlay.ShowOverlay(ExtraHandle(focusedPanel)));else Check(OpenVR.Overlay.HideOverlay(ExtraHandle(focusedPanel)));}}Emit(new{type="watch-visibility",visible=next});Emit(new{type="watch-focus",armed=next});}
 static object WatchCommand(Dictionary<string,object> c){string style=Text(c,"style");if(style=="watch"||style=="toolbar"){watchStyle=style;if(style=="watch")RestoreFocusedPanel();}if(Text(c,"enabled").ToLower()=="false"){string anchor=Text(c,"anchor");if(anchor=="wrist-left"||anchor=="wrist-right")watchAnchor=anchor;watchWidth=Math.Max(watchStyle=="watch"?.05:.10,Math.Min(watchStyle=="watch"?.09:.18,Number(c,"width",watchWidth)));HideWatch();}else ShowWatch(Text(c,"anchor")==""?watchAnchor:Text(c,"anchor"),Number(c,"width",watchWidth));return new{enabled=watchEnabled,anchor=watchAnchor,width=watchWidth,style=watchStyle};}
 static readonly TrackedDevicePose_t[] watchPoses=new TrackedDevicePose_t[OpenVR.k_unMaxTrackedDeviceCount];
 static void TickWatchFocus(){if(fixture||watchHandle==0)return;double now=Clock.Elapsed.TotalSeconds;if(now-lastWatchCheck<.033)return;lastWatchCheck=now;bool show=false;if(watchEnabled&&!OpenVR.Overlay.IsDashboardVisible()){uint hand=system.GetTrackedDeviceIndexForControllerRole(watchAnchor=="wrist-left"?ETrackedControllerRole.LeftHand:ETrackedControllerRole.RightHand);if(hand!=OpenVR.k_unTrackedDeviceIndexInvalid&&system.IsTrackedDeviceConnected(hand)){system.GetDeviceToAbsoluteTrackingPose(ETrackingUniverseOrigin.TrackingUniverseStanding,0,watchPoses);if(watchPoses[0].bPoseIsValid&&watchPoses[hand].bPoseIsValid)show=WatchInView(watchPoses[0].mDeviceToAbsoluteTracking,Multiply(watchPoses[hand].mDeviceToAbsoluteTracking,WatchTransform(watchAnchor)),watchVisible);}}SetWatchVisible(show);}
 static void WatchTests(){var head=Identity();var face=Identity();face.m11=-.4f;if(!WatchInView(head,face,false))throw new Exception("Visible watch was hidden.");if(WatchInView(Rotation(90,0),face,true))throw new Exception("Watch stayed visible when looking away.");face.m10=-1;if(WatchInView(head,face,true))throw new Exception("Watch backside was visible.");face=Identity();face.m11=-2;if(WatchInView(head,face,true))throw new Exception("Distant watch was visible.");face=Identity();face.m11=-.4f;face.m3=.24f;if(WatchInView(head,face,false)||!WatchInView(head,face,true))throw new Exception("Gaze hysteresis failed.");var left=WatchTransform("wrist-left");var right=WatchTransform("wrist-right");if(left.m3>=-.05f||right.m3<=.05f||Math.Abs(left.m3+right.m3)>.00001||left.m7<0||right.m7<0||left.m2<.99f||right.m2>-.99f||Math.Abs(left.m6)>.001||Math.Abs(right.m6)>.001)throw new Exception("Dorsal mounts must mirror on the outer sides and face inward, not beneath the grip.");
 var leftHand=Rotation(-90,0);leftHand.m3=-.18f;leftHand.m7=-.18f;leftHand.m11=-.4f;var rightHand=Rotation(90,0);rightHand.m3=.18f;rightHand.m7=-.18f;rightHand.m11=-.4f;var looking=Rotation(0,-25);if(!WatchInView(looking,Multiply(leftHand,left),false)||!WatchInView(looking,Multiply(rightHand,right),false))throw new Exception("A mirrored wrist-check pose must reveal either hand.");
 Emit(new{type="watch-selftest",passed=true,gazeCases=5,dorsalMountCases=2,pointToArm=false});}
}
